    43|async function runTest(def: TestDef): Promise<QATestResult> {
    44|  const start = Date.now();
    45|  try {
    46|    const outcome = await def.fn();
    47|    return makeResult(def, outcome, Date.now() - start);
    48|  } catch (err) {
    49|    return makeResult(
    50|      def,
    51|      {
    52|        actual: 'Exception thrown',
    53|        status: 'ERROR',
    54|        errorDetail: String(err).slice(0, 500),
    55|        evidenceRef: 'exception',
    56|      },
    57|      Date.now() - start,
    58|    );
    59|  }
